                                <div class="progress-bar">
                                    <div class="progress-fill" id="excitement-bar" style="width: 0%"></div>
                                </div>
                            </div>
                            <div class="stat-item">
                                <div class="stat-label">
                                    <span class="stat-name">贞操观念</span>
                                    <span class="stat-value" id="principle-value">--/100</span>
