                            <div class="stat-item">
                                <div class="stat-label">
                                    <span class="stat-name">抗拒度</span>
                                    <span class="stat-value" id="autonomy-value">--/100</span>
                                </div>
                                <div class="progress-bar">
                                    <div class="progress-fill" id="autonomy-bar" style="width: 0%"></div>
