        .choice-option:active {
            transform: translateY(0) scale(0.98);
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
        }
        /* 响应式调整 */
        @media (max-width: 768px) {
            .stats-grid {
                grid-template-columns: 1fr;
            }
            .status-container {
                grid-template-columns: 1fr;
            }
            .info-bar {
                flex-direction: column;
                gap: 8px;
            }
            .numeric-stats {
                grid-template-columns: repeat(2, 1fr);
            }
            .choice-container {
                padding: 16px;
                margin-top: 16px;
                max-width: 100%;
            }
            .choice-option {
                padding: 12px 14px;
            }
        }
        @media (max-width: 480px) {
            .container {
                max-width: 100%;
                padding: 10px;
            }
            .choice-container {
                padding: 12px;
                margin-top: 12px;
            }
            .choice-title {
                font-size: 1.1em;
                margin-bottom: 12px;
            }
            .choice-option {
                padding: 10px 12px;
                font-size: 0.95em;
            }
            .choice-wrapper {
                gap: 8px;
            }
        }
    </style>
</head>
<body>
