    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const errorMessage = document.getElementById('error-message');
            const loadingIndicator = document.getElementById('loading-indicator');
            const mainContent = document.getElementById('main-content');
            const perspectiveTabs = document.getElementById('perspective-tabs');
            const perspectivesContent = document.getElementById('perspectives-content');
            const infoBar = document.getElementById('info-bar');
            const choiceContainer = document.getElementById('choice-container');
            const choiceWrapper = document.getElementById('choice-wrapper');

            // 主页面切换
            const mainTabs = document.querySelectorAll('.main-tab');
            const mainPages = document.querySelectorAll('.main-page');

            mainTabs.forEach(tab => {
                tab.addEventListener('click', function() {
                    // 移除所有标签和页面的active类
                    mainTabs.forEach(t => t.classList.remove('active'));
                    mainPages.forEach(p => p.classList.remove('active'));

                    // 添加active类到当前标签和对应页面
                    this.classList.add('active');
                    const tabId = this.getAttribute('data-tab');
                    document.getElementById(`${tabId}-page`).classList.add('active');
                });
            });

            // 存储解析后的数据
            let parsedData = {
                date: '',
                time: '',
                weekday: '',
                temperature: '',
                location: '',
                mainContent: '',
                characters: [],
                currentCharacterIndex: 0,
                choiceOptions: [] // 存储选择框选项
            };

            let currentMessageId = null;
            let initialCheckTimeout = null;
            let psychologicalRadarChart = null;

            // 获取当前iframe的名称，用于确定所在消息框
            function getIframeName() {
                try {
                    if (typeof window.getIframeName === 'function') {
                        return window.getIframeName();
                    } else {
                        return window.name || '';
                    }
                } catch (error) {
                    console.error("获取iframe名称出错:", error);
                    return '';
                }
            }

            // 从iframe名称中提取消息ID
            function getMessageIdFromIframeName(iframeName) {
                try {
                    if (iframeName.startsWith('message-iframe-')) {
                        const parts = iframeName.split('-');
                        if (parts.length >= 3) {
                            return parseInt(parts[2]);
                        }
                    }

                    if (typeof window.getCurrentMessageId === 'function') {
                        return window.getCurrentMessageId();
                    }

                    return null;
                } catch (error) {
                    console.error("从iframe名称提取消息ID出错:", error);
                    return null;
                }
            }

            // 获取当前消息内容
            async function getCurrentMessageContent() {
                try {
                    const iframeName = getIframeName();
                    currentMessageId = getMessageIdFromIframeName(iframeName);

                    if (currentMessageId === null) {
                        throw new Error('无法确定当前消息ID');
                    }

                    if (typeof window.getChatMessages === 'function') {
                        const messages = await window.getChatMessages(currentMessageId.toString());
                        if (messages && messages.length > 0) {
                            return messages[0].message || '';
                        }
                    } 
                    else if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                        const chat = SillyTavern.getContext().chat;
                        if (chat && chat.length > currentMessageId) {
                            return chat[currentMessageId].mes || '';
                        }
                    } 
                    else {
                        const messageElement = document.querySelector(`div.mes[mesid="${currentMessageId}"]`, window.parent.document);
                        if (messageElement) {
                            const textElement = messageElement.querySelector('div.mes_text');
                            if (textElement) {
                                return textElement.textContent || '';
                            }
                        }
                    }

                    throw new Error('无法获取当前消息内容');
                } catch (error) {
                    console.error("获取当前消息内容出错:", error);
                    return '';
                }
            }

            // 解析时间地点天气信息
            function parseInfoData(content) {
                // 日期
                const dateMatch = content.match(/\[DT:([\s\S]*?)\]/);
                if (dateMatch && dateMatch[1]) {
                    parsedData.date = dateMatch[1].trim();
                }

                // 时间
                const timeMatch = content.match(/\[TM:([\s\S]*?)\]/);
                if (timeMatch && timeMatch[1]) {
                    parsedData.time = timeMatch[1].trim();
                }

                // 星期
                const weekdayMatch = content.match(/\[WK:([\s\S]*?)\]/);
                if (weekdayMatch && weekdayMatch[1]) {
                    parsedData.weekday = weekdayMatch[1].trim();
                }

                // 温度
                const tempMatch = content.match(/\[TMP:([\s\S]*?)\]/);
                if (tempMatch && tempMatch[1]) {
                    parsedData.temperature = tempMatch[1].trim();
                }

                // 地点
                const posMatch = content.match(/\[POS:([\s\S]*?)\]/);
                if (posMatch && posMatch[1]) {
                    parsedData.location = posMatch[1].trim();
                }

                // 更新信息栏
                document.getElementById('date-info').textContent = `日期: ${parsedData.date || '--'}`;
                document.getElementById('time-info').textContent = `时间: ${parsedData.time || '--'}`;
                document.getElementById('weekday-info').textContent = `星期: ${parsedData.weekday || '--'}`;
                document.getElementById('temp-info').textContent = `温度: ${parsedData.temperature || '--'}`;
                document.getElementById('location-info').textContent = `地点: ${parsedData.location || '--'}`;
            }

            // 解析状态数据
            function parseStatusData(content) {
                // 查找所有状态数据块
                const allStatusBlocks = content.match(/<StatusBlocks>([\s\S]*?)<\/StatusBlocks>/g);
                if (!allStatusBlocks || allStatusBlocks.length === 0) return;

                // 重置角色数组
                parsedData.characters = [];
                parsedData.currentCharacterIndex = 0;

                // 处理每个状态数据块
                for (let block of allStatusBlocks) {
                    const statusMatch = block.match(/<StatusBlocks>([\s\S]*?)<\/StatusBlocks>/);
                    if (!statusMatch || !statusMatch[1]) continue;

                    const statusContent = statusMatch[1].trim();

                    // 使用非贪婪模式匹配所有状态数据，即使其中包含换行符或特殊字符
                    const statusParts = [];
                    let bracketLevel = 0;
                    let currentPart = '';

                    for (let i = 0; i < statusContent.length; i++) {
                        const char = statusContent[i];

                        if (char === '[' && (i === 0 || statusContent[i-1] !== '\\')) {
                            if (bracketLevel === 0) {
                                currentPart = '[';
                            } else {
                                currentPart += char;
                            }
                            bracketLevel++;
                        } 
                        else if (char === ']' && (i === 0 || statusContent[i-1] !== '\\')) {
                            bracketLevel--;
                            if (bracketLevel === 0) {
                                currentPart += ']';
                                statusParts.push(currentPart);
                                currentPart = '';
                            } else {
                                currentPart += char;
                            }
                        } 
                        else {
                            if (bracketLevel > 0) {
                                currentPart += char;
                            }
                        }
                    }

                    if (!statusParts || statusParts.length < 20) continue;

                    // 提取中括号内的内容（保留所有格式，包括换行符）
                    const cleanData = statusParts.map(part => {
                        // 移除最外层的中括号，保留内部的一切字符
                        return part.substring(1, part.length - 1);
                    });

                    // 创建角色数据对象
                    const characterData = {
                        characterName: cleanData[0] || '',
                        avatarUrl: cleanData[1] || '',
                        physiological: {
                            vitality: 0,
                            vitalityText: '',
                            satisfaction: 0,
                            satisfactionText: '',
                            cleanliness: 0,
                            cleanlinessText: '',
                            specialEffect: ''
                        },
                        psychological: {
                            stability: 0,
                            stabilityText: '',
                            care: 0,
                            careText: '',
                            responsibility: 0,
                            responsibilityText: '',
                            alertness: 0,
                            alertnessText: '',
                            cooperation: 0,
                            cooperationText: ''
                        },
                        progress: {
                            statusPoints: 0,
                            statusPointsText: '',
                            excitement: 0,
                            excitementText: '',
                            principle: 0,
                            principleText: '',
                            autonomy: 0,
                            autonomyText: ''
                        },
                        behavior: {
                            totalInteractions: 0,
                            interactionA: 0,
                            interactionB: 0,
                            interactionC: 0,
                            personalInteractions: 0,
                            groupInteractions: 0,
                            highlightMoments: 0,
                            specialStatus: '',
                            eventRecord: '',
                            memoryRecord: ''
                        },
                        characterStatus: {
                            status1: '',
                            status2: '',
                            status3: '',
                            status4: ''
                        }
                    };

                    // 基础生理状态组
                    const physiologicalValues = [
                        cleanData[2], // 体力值
                        cleanData[3], // 饥饿度
                        cleanData[4], // 清洁度
                        cleanData[5]  // 药物影响
                    ];

                    // 核心心理状态组
                    const psychologicalValues = [
                        cleanData[6], // SAN值
                        cleanData[7], // 羞耻心
                        cleanData[8], // 罪恶感
                        cleanData[9], // 恐惧感
                        cleanData[10] // 屈服度
                    ];

                    // 调教进展指标组
                    const progressValues = [
                        cleanData[11], // 堕落值
                        cleanData[12], // 淫欲度
                        cleanData[13], // 贞操观念
                        cleanData[14]  // 抗拒度
                    ];

                    // 行为记录与经验组
                    const behaviorValues = [
                        cleanData[15], // 性行为
                        cleanData[16], // 口交次数
                        cleanData[17], // 肛交次数
                        cleanData[18], // 阴道性交次数
                        cleanData[19], // 自慰次数
                        cleanData[20], // 群交次数
                        cleanData[21], // 高潮次数
                        cleanData[22], // 受孕状态
                        cleanData[23], // 事件记录
                        cleanData[24]  // 回忆记录
                    ];

                    // 角色基础属性（检查是否有额外的ST标签）
                    const characterStatusValues = [];

                    // 查找所有ST标签
                    for (let i = 25; i < cleanData.length; i++) {
                        const statusText = cleanData[i] || '';
                        if (statusText.startsWith('ST:')) {
                            characterStatusValues.push(statusText.substring(3));
                        }
                    }

                    // 处理基础生理状态
                    const parsePercentage = (str) => {
                        const parts = str.split('/');
                        if (parts.length === 2) {
                            const current = parseInt(parts[0]);
                            const max = parseInt(parts[1]);
                            if (!isNaN(current) && !isNaN(max) && max !== 0) {
                                return {
                                    current: current,
                                    max: max,
                                    percentage: (current / max) * 100
                                };
                            }
                        }
                        return { current: 0, max: 100, percentage: 0 };
                    };

                    // 解析基础生理状态
                    const vitalityData = parsePercentage(physiologicalValues[0]);
                    const satisfactionData = parsePercentage(physiologicalValues[1]);
                    const cleanlinessData = parsePercentage(physiologicalValues[2]);

                    characterData.physiological = {
                        vitality: vitalityData.percentage,
                        vitalityText: physiologicalValues[0],
                        satisfaction: satisfactionData.percentage,
                        satisfactionText: physiologicalValues[1],
                        cleanliness: cleanlinessData.percentage,
                        cleanlinessText: physiologicalValues[2],
                        specialEffect: physiologicalValues[3]
                    };

                    // 解析核心心理状态
                    const stabilityData = parsePercentage(psychologicalValues[0]);
                    const careData = parsePercentage(psychologicalValues[1]);
                    const responsibilityData = parsePercentage(psychologicalValues[2]);
                    const alertnessData = parsePercentage(psychologicalValues[3]);
                    const cooperationData = parsePercentage(psychologicalValues[4]);

                    characterData.psychological = {
                        stability: stabilityData.percentage,
                        stabilityText: psychologicalValues[0],
                        care: careData.percentage,
                        careText: psychologicalValues[1],
                        responsibility: responsibilityData.percentage,
                        responsibilityText: psychologicalValues[2],
                        alertness: alertnessData.percentage,
                        alertnessText: psychologicalValues[3],
                        cooperation: cooperationData.percentage,
                        cooperationText: psychologicalValues[4]
                    };

                    // 解析调教进展指标
                    const statusPointsData = parsePercentage(progressValues[0]);
                    const excitementData = parsePercentage(progressValues[1]);
                    const principleData = parsePercentage(progressValues[2]);
                    const autonomyData = parsePercentage(progressValues[3]);

                    characterData.progress = {
                        statusPoints: statusPointsData.percentage,
                        statusPointsText: progressValues[0],
                        excitement: excitementData.percentage,
                        excitementText: progressValues[1],
                        principle: principleData.percentage,
                        principleText: progressValues[2],
                        autonomy: autonomyData.percentage,
                        autonomyText: progressValues[3]
                    };

                    // 解析行为记录与经验
                    characterData.behavior = {
                        totalInteractions: behaviorValues[0],
                        interactionA: behaviorValues[1],
                        interactionB: behaviorValues[2],
                        interactionC: behaviorValues[3],
                        personalInteractions: behaviorValues[4],
                        groupInteractions: behaviorValues[5],
                        highlightMoments: behaviorValues[6],
                        specialStatus: behaviorValues[7],
                        eventRecord: behaviorValues[8],
                        memoryRecord: behaviorValues[9]
                    };

                    // 保存角色基础属性
                    characterData.characterStatus = {
                        status1: characterStatusValues[0] || '',
                        status2: characterStatusValues[1] || '',
                        status3: characterStatusValues[2] || '',
                        status4: characterStatusValues[3] || ''
                    };

                    // 将角色添加到数组
                    parsedData.characters.push(characterData);
                }

                // 更新当前角色状态页面
                updateCharacterCounter();
                updateStatusPage();
            }

            // 解析选择框数据
            function parseChoiceData(content) {
                // 重置选择框数据
                parsedData.choiceOptions = [];

                // 查找选择框数据块
                const checkboxMatch = content.match(/<Checkbox>([\s\S]*?)<\/Checkbox>/);
                if (!checkboxMatch || !checkboxMatch[1]) {
                    // 没有找到选择框数据，隐藏选择框
                    choiceContainer.style.display = 'none';
                    return;
                }

                const choiceContent = checkboxMatch[1].trim();

                // 提取选项数据
                const optionParts = [];
                let bracketLevel = 0;
                let currentPart = '';

                for (let i = 0; i < choiceContent.length; i++) {
                    const char = choiceContent[i];

                    if (char === '[' && (i === 0 || choiceContent[i-1] !== '\\')) {
                        if (bracketLevel === 0) {
                            currentPart = '[';
                        } else {
                            currentPart += char;
                        }
                        bracketLevel++;
                    } 
                    else if (char === ']' && (i === 0 || choiceContent[i-1] !== '\\')) {
                        bracketLevel--;
                        if (bracketLevel === 0) {
                            currentPart += ']';
                            optionParts.push(currentPart);
                            currentPart = '';
                        } else {
                            currentPart += char;
                        }
                    } 
                    else {
                        if (bracketLevel > 0) {
                            currentPart += char;
                        }
                    }
                }

                // 处理选项
                if (optionParts && optionParts.length > 0) {
                    // 提取中括号内的内容
                    parsedData.choiceOptions = optionParts.map(part => {
                        // 移除最外层的中括号
                        return part.substring(1, part.length - 1);
                    });

                    // 更新选择框
                    updateChoiceBox();
                } else {
                    // 没有选项，隐藏选择框
                    choiceContainer.style.display = 'none';
                }
            }

            // 更新选择框显示
            function updateChoiceBox() {
                // 清空当前选项
                choiceWrapper.innerHTML = '';

                // 有选项时显示选择框，否则隐藏
                if (parsedData.choiceOptions.length > 0) {
                    // 创建选项按钮
                    parsedData.choiceOptions.forEach(option => {
                        const optionElement = document.createElement('div');
                        optionElement.className = 'choice-option';
                        optionElement.textContent = option;
                        optionElement.addEventListener('click', function() {
                            handleChoiceClick(option);
                        });
                        choiceWrapper.appendChild(optionElement);
                    });

                    // 显示选择框
                    choiceContainer.style.display = 'block';
                } else {
                    // 隐藏选择框
                    choiceContainer.style.display = 'none';
                }
            }

            // 处理选项点击事件
            function handleChoiceClick(optionText) {
                try {
                    // 格式化发送的文本
                    const requestText = `<request:{{user}}选择了[${optionText}]>`;

                    // 发送选项到酒馆并触发回复
                    if (typeof window.triggerSlash === 'function') {
                        window.triggerSlash(`/send ${requestText} || /trigger`);
                    } else if (window.parent && typeof window.parent.triggerSlash === 'function') {
                        window.parent.triggerSlash(`/send ${requestText} || /trigger`);
                    } else {
                        console.error('无法找到triggerSlash函数');

                        // 尝试其他方法发送消息
                        if (window.parent && window.parent.document) {
                            const textareaElement = window.parent.document.querySelector('#send_textarea');
                            const sendButton = window.parent.document.querySelector('#send_but');

                            if (textareaElement && sendButton) {
                                textareaElement.value = requestText;
                                sendButton.click();
                            } else {
                                console.error('无法找到发送消息的元素');
                            }
                        }
                    }
                } catch (error) {
                    console.error('发送选项时出错:', error);
                }
            }

            // 更新角色状态页面
            function updateStatusPage() {
                // 检查是否有角色数据
                if (parsedData.characters.length === 0) {
                    return;
                }

                // 获取当前角色数据
                const currentCharacter = parsedData.characters[parsedData.currentCharacterIndex];

                // 更新角色信息
                document.getElementById('character-name').textContent = currentCharacter.characterName || '--';

                // 更新头像
                const avatarImg = document.getElementById('character-avatar');
                if (currentCharacter.avatarUrl && currentCharacter.avatarUrl !== '--') {
                    avatarImg.src = currentCharacter.avatarUrl;
                } else {
                    avatarImg.src = 'https://via.placeholder.com/200x200?text=无头像数据';
                }

                // 更新角色基础属性
                document.getElementById('character-status1').textContent = currentCharacter.characterStatus.status1 || '--';
                document.getElementById('character-status2').textContent = currentCharacter.characterStatus.status2 || '--';
                document.getElementById('character-status3').textContent = currentCharacter.characterStatus.status3 || '--';
                document.getElementById('character-status4').textContent = currentCharacter.characterStatus.status4 || '--';

                // 更新基础生理状态组
                document.getElementById('vitality-value').textContent = currentCharacter.physiological.vitalityText || '--/100';
                document.getElementById('vitality-bar').style.width = `${currentCharacter.physiological.vitality}%`;

                document.getElementById('satisfaction-value').textContent = currentCharacter.physiological.satisfactionText || '--/100';
                document.getElementById('satisfaction-bar').style.width = `${currentCharacter.physiological.satisfaction}%`;

                document.getElementById('cleanliness-value').textContent = currentCharacter.physiological.cleanlinessText || '--/100';
                document.getElementById('cleanliness-bar').style.width = `${currentCharacter.physiological.cleanliness}%`;

                document.getElementById('special-effect').textContent = currentCharacter.physiological.specialEffect || '--';

                // 更新心理状态雷达图
                updatePsychologicalRadar();

                // 更新核心心理状态值显示
                document.getElementById('stability-value').textContent = currentCharacter.psychological.stabilityText || '--/100';
                document.getElementById('care-value').textContent = currentCharacter.psychological.careText || '--/100';
                document.getElementById('responsibility-value').textContent = currentCharacter.psychological.responsibilityText || '--/100';
                document.getElementById('alertness-value').textContent = currentCharacter.psychological.alertnessText || '--/100';
                document.getElementById('cooperation-value').textContent = currentCharacter.psychological.cooperationText || '--/100';

                // 更新调教进展指标组
                document.getElementById('status-points-value').textContent = currentCharacter.progress.statusPointsText || '--/100';
                document.getElementById('status-points-bar').style.width = `${currentCharacter.progress.statusPoints}%`;

                document.getElementById('excitement-value').textContent = currentCharacter.progress.excitementText || '--/100';
                document.getElementById('excitement-bar').style.width = `${currentCharacter.progress.excitement}%`;

                document.getElementById('principle-value').textContent = currentCharacter.progress.principleText || '--/100';
                document.getElementById('principle-bar').style.width = `${currentCharacter.progress.principle}%`;

                document.getElementById('autonomy-value').textContent = currentCharacter.progress.autonomyText || '--/100';
                document.getElementById('autonomy-bar').style.width = `${currentCharacter.progress.autonomy}%`;

                // 更新行为记录与经验组
                document.getElementById('total-interactions').textContent = currentCharacter.behavior.totalInteractions || '--';
                document.getElementById('interaction-a').textContent = currentCharacter.behavior.interactionA || '--';
                document.getElementById('interaction-b').textContent = currentCharacter.behavior.interactionB || '--';
                document.getElementById('interaction-c').textContent = currentCharacter.behavior.interactionC || '--';
                document.getElementById('personal-interactions').textContent = currentCharacter.behavior.personalInteractions || '--';
                document.getElementById('group-interactions').textContent = currentCharacter.behavior.groupInteractions || '--';
                document.getElementById('highlight-moments').textContent = currentCharacter.behavior.highlightMoments || '--';

                document.getElementById('special-status').textContent = currentCharacter.behavior.specialStatus || '--';
                document.getElementById('event-record').textContent = currentCharacter.behavior.eventRecord || '--';
                document.getElementById('memory-record').textContent = currentCharacter.behavior.memoryRecord || '--';
            }

            // 更新心理状态雷达图
            function updatePsychologicalRadar() {
                const ctx = document.getElementById('psychological-radar').getContext('2d');

                // 检查是否有角色数据
                if (parsedData.characters.length === 0) {
                    return;
                }

                // 获取当前角色数据
                const currentCharacter = parsedData.characters[parsedData.currentCharacterIndex];

                // 如果已有图表，先销毁
                if (psychologicalRadarChart) {
                    psychologicalRadarChart.destroy();
                }

                // 创建新图表
                psychologicalRadarChart = new Chart(ctx, {
                    type: 'radar',
                    data: {
                        labels: ['SAN值', '羞耻心', '罪恶感', '恐惧感', '屈服度'],
                        datasets: [{
                            label: '心理状态',
                            data: [
                                currentCharacter.psychological.stability,
                                currentCharacter.psychological.care,
                                currentCharacter.psychological.responsibility,
                                currentCharacter.psychological.alertness,
                                currentCharacter.psychological.cooperation
                            ],
                            backgroundColor: 'rgba(60, 60, 60, 0.4)',
                            borderColor: 'rgba(170, 170, 170, 0.8)',
                            borderWidth: 2,
                            pointBackgroundColor: '#707070',
                            pointBorderColor: '#f0f0f0',
                            pointHoverBackgroundColor: '#fff',
                            pointHoverBorderColor: 'rgba(200, 200, 200, 1)'
                        }]
                    },
                    options: {
                        elements: {
                            line: {
                                borderWidth: 3
                            }
                        },
                        scales: {
                            r: {
                                angleLines: {
                                    color: 'rgba(180, 180, 180, 0.2)'
                                },
                                grid: {
                                    color: 'rgba(180, 180, 180, 0.2)'
                                },
                                pointLabels: {
                                    color: '#c0c0c0',
                                    font: {
                                        size: 12,
                                        family: "'SF Pro Text', 'Segoe UI', sans-serif",
                                        weight: '500'
                                    }
                                },
                                ticks: {
                                    display: false, 
                                    backdropColor: 'transparent',
                                    color: '#c0c0c0'
                                },
                                suggestedMin: 0,
                                suggestedMax: 100
                            }
                        },
                        plugins: {
                            legend: {
                                display: false
                            }
                        }
                    }
                });
            }

            // 更新角色计数器
            function updateCharacterCounter() {
                const totalCharacters = parsedData.characters.length;
                const currentIndex = parsedData.currentCharacterIndex + 1;
                document.getElementById('character-counter').textContent = `${currentIndex}/${totalCharacters}`;

                // 更新按钮状态
                document.getElementById('prev-character').classList.toggle('disabled', totalCharacters <= 1 || currentIndex === 1);
                document.getElementById('next-character').classList.toggle('disabled', totalCharacters <= 1 || currentIndex === totalCharacters);
            }

            // 下一个角色
            function nextCharacter() {
                const totalCharacters = parsedData.characters.length;
                if (totalCharacters <= 1 || parsedData.currentCharacterIndex >= totalCharacters - 1) {
                    return; // 已经是最后一个角色
                }

                parsedData.currentCharacterIndex++;
                updateCharacterCounter();
                updateStatusPage();
            }

            // 上一个角色
            function prevCharacter() {
                if (parsedData.characters.length <= 1 || parsedData.currentCharacterIndex <= 0) {
                    return; // 已经是第一个角色
                }

                parsedData.currentCharacterIndex--;
                updateCharacterCounter();
                updateStatusPage();
            }

            // 提取主要内容（排除状态数据标签和选择框标签中的内容）
            function extractMainContent(content) {
                // 创建临时content副本
                let mainContent = content;

                // 移除状态数据标签及其内容 - 使用[\s\S]*?匹配多行文本
                const statusRegex = /<StatusBlocks>([\s\S]*?)<\/StatusBlocks>/g;
                mainContent = mainContent.replace(statusRegex, '');

                // 移除选择框标签及其内容
                const checkboxRegex = /<Checkbox>([\s\S]*?)<\/Checkbox>/g;
                mainContent = mainContent.replace(checkboxRegex, '');

                // 移除时间地点天气信息 - 使用[\s\S]*?匹配多行文本
                mainContent = mainContent.replace(/\[(DT|TM|WK|TMP|POS):([\s\S]*?)\]/g, '');

                // 清理额外的空行但保留基本格式
                mainContent = mainContent.replace(/\n{4,}/g, '\n\n\n').trim();

                return mainContent;
            }

            // 解析消息功能
            async function parseMessage() {
                errorMessage.style.display = 'none';

                try {
                    // 获取当前消息内容
                    const messageContent = await getCurrentMessageContent();
                    if (!messageContent) {
                        throw new Error('获取消息内容失败');
                    }

                    // 检查消息中是否包含<content>标签 - 使用[\s\S]*?可以匹配包含换行符的内容
                    if (!messageContent.includes('<content>') || !messageContent.includes('</content>')) {
                        // 没有找到内容标签，清空并隐藏
                        mainContent.innerHTML = '';
                        loadingIndicator.style.display = 'none';
                        choiceContainer.style.display = 'none';
                        return;
                    }

                    // 提取<content>标签内的内容 - 使用[\s\S]*?匹配多行文本
                    const contentRegex = /<content>([\s\S]*?)<\/content>/;
                    const contentMatch = messageContent.match(contentRegex);

                    if (!contentMatch || !contentMatch[1]) {
                        throw new Error('<content>标签内没有有效内容');
                    }

                    const content = contentMatch[1];

                    // 解析时间地点天气信息
                    parseInfoData(content);

                    // 解析状态数据
                    parseStatusData(content);

                    // 解析选择框数据
                    parseChoiceData(content);

                    // 提取主要文本内容（移除状态数据标签内容和选择框内容）
                    const mainText = extractMainContent(content);

                    // 隐藏加载指示器
                    loadingIndicator.style.display = 'none';

                    // 更新主内容区域，保留原始格式
                    mainContent.innerHTML = mainText;

                } catch (error) {
                    console.error(error);
                    errorMessage.textContent = `解析错误: ${error.message}`;
                    errorMessage.style.display = 'block';
                    loadingIndicator.style.display = 'none';
                    choiceContainer.style.display = 'none';
                }
            }

            // 设置自动解析
            function setupAutoCheck() {
                // 立即执行一次解析
                parseMessage();

                // 由于初始加载时可能数据还未准备好，设置延迟检测
                initialCheckTimeout = setTimeout(() => {
                    parseMessage();
                }, 1000); // 1秒后再次检测
            }

            // 启动检测
            setupAutoCheck();

            // 添加角色导航按钮事件监听
            document.getElementById('prev-character').addEventListener('click', function() {
                if (!this.classList.contains('disabled')) {
                    prevCharacter();
                }
            });

            document.getElementById('next-character').addEventListener('click', function() {
                if (!this.classList.contains('disabled')) {
                    nextCharacter();
                }
            });
        });
    </script>
</body>
</html>
